    private void notify(Ticket t,UUID event,boolean assignment,String type,Instant time,java.util.function.Predicate<UUID> eligible){
        var targets=new HashSet<UUID>();targets.add(t.summary.creatorAccountId());var assigned=assignment(t.summary).assigneeAccountId();if(assigned!=null)targets.add(assigned);
        for(UUID recipient:targets){if(!eligible.test(recipient))continue;
            jdbc.update("INSERT INTO orders.organization_support_notice(id,organization_id,ticket_id,event_id,message_event_id,assignment_event_id,recipient_account_id,type,created_at,version) SELECT ?,?,?,?,?,?,?,?,?,1 WHERE orders.organization_support_permission(?,?,?,'support.read') AND EXISTS(SELECT 1 FROM orders.organization_support_notification_preference p WHERE p.organization_id=? AND p.account_id=? AND p.enabled AND ?=ANY(p.event_types)) ON CONFLICT(event_id,recipient_account_id) DO NOTHING",UUID.randomUUID(),t.summary.organizationId(),t.summary.id(),event,assignment?null:event,assignment?event:null,recipient,type,ts(time),t.summary.organizationId(),recipient,t.summary.facilityId(),t.summary.organizationId(),recipient,type);
        }
    }
